// Builds the payload for submit_request() and classifies the request.
// Only whitelisted fields are passed on, so a client cannot set category,
// priority or status itself. The requester's choice (request_type) is kept
// unless the title/description clearly point to another category; the reason
// is stored with the request for audit.
const RULES = {
  ACCESS:     ['access', 'permission', 'login', 'log in', 'account', 'password', 'role', 'grant', 'unlock', 'دسترسی', 'رمز عبور'],
  DATA_FIX:   ['fix', 'wrong', 'incorrect', 'mismatch', 'duplicate', 'missing', 'correct', 'inconsisten', 'اصلاح', 'اشتباه', 'مغایرت'],
  REPORT:     ['report', 'dashboard', 'kpi', 'chart', 'export', 'گزارش', 'داشبورد'],
  AUTOMATION: ['automat', 'workflow', 'bot', 'schedul', 'integrat', 'اتوماسیون', 'خودکار'],
};

// Latin keywords match at a word start ("automat" → automate, automation);
// other scripts have no ASCII word boundaries, so they use a plain substring.
const has = (text, word) => /^[a-z ]+$/.test(word)
  ? new RegExp(`\\b${word}`, 'i').test(text)
  : text.includes(word);

const str = (v) => (v === undefined || v === null ? '' : String(v).trim());

return $input.all().map(({ json }) => {
  const b = json.body && typeof json.body === 'object' ? json.body : {};
  const title = str(b.title);
  const description = str(b.description);
  const chosen = str(b.request_type).toUpperCase();

  const scores = Object.entries(RULES)
    .map(([code, words]) => {
      const inTitle = words.filter((w) => has(title, w));
      const inDesc = words.filter((w) => has(description, w));
      return { code, points: inTitle.length * 2 + inDesc.length, hits: [...new Set([...inTitle, ...inDesc])] };
    })
    .sort((x, y) => y.points - x.points);

  const top = scores[0];
  const chosenPoints = scores.find((s) => s.code === chosen)?.points ?? 0;
  const tied = scores.filter((s) => s.points === top.points).length > 1;

  let category = chosen;
  let reason;
  if (top.points === 0) {
    reason = 'No category keywords found; kept the requester\'s choice';
  } else if (chosenPoints === top.points) {
    reason = `Keywords agree with the requester's choice (${top.hits.join(', ')})`;
  } else if (tied) {
    reason = 'Keywords point to several categories; kept the requester\'s choice';
  } else {
    category = top.code;
    reason = `Reclassified from ${chosen || 'none'} to ${top.code}: keywords ${top.hits.join(', ')}`;
  }

  return {
    json: {
      payload: {
        requester_name: str(b.requester_name),
        requester_email: str(b.requester_email),
        company: str(b.company),
        department: str(b.department),
        request_type: chosen,
        category,
        classification_reason: reason,
        title,
        description,
        justification: str(b.justification),
        needed_by: str(b.needed_by),
        declared_priority: str(b.declared_priority).toUpperCase(),
        idempotency_key: str(b.idempotency_key),
        source: 'appsmith',
      },
    },
  };
});
